import{_ as o,B as i,o as r,c as l,a8 as d,a,f as t,E as n}from"./chunks/framework.CNIpabDg.js";const x=JSON.parse(`{"title":"Headless Xila runtime","description":"Exact shell and guest commands, image defaults, persistence, mounts, and limits of Xila's headless runtime.","frontmatter":{"layout":"doc","docType":"reference","description":"Exact shell and guest commands, image defaults, persistence, mounts, and limits of Xila's headless runtime."},"headers":[],"relativePath":"reference/container-runtime.md","filePath":"reference/container-runtime.md","lastUpdated":1793145952000}`),c={name:"reference/container-runtime.md"};function m(u,e,p,h,g,b){const s=i("CodeReference");return r(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[5]||(e[5]=d(`<h1 id="headless-xila-runtime" tabindex="-1">Headless Xila runtime <a class="header-anchor" href="#headless-xila-runtime" aria-label="Permalink to &quot;Headless Xila runtime&quot;">​</a></h1><p>The <code>xila-runtime</code> binary runs a Xila <strong>command-line shell</strong> or a VFS executable without a graphical desktop. It can be built as a native binary or used in a Linux/amd64 OCI image. This is <strong>not</strong> the development image that contains Rust and build tools.</p><h2 id="image-and-executable" tabindex="-1">Image and executable <a class="header-anchor" href="#image-and-executable" aria-label="Permalink to &quot;Image and executable&quot;">​</a></h2><p>Platforms&#39; <a href="https://github.com/xila-project/platforms/actions/workflows/runtime.yml" target="_blank" rel="noreferrer">runtime workflow</a> builds and smoke-tests the image from <code>Dockerfile.runtime</code> and publishes to <code>ghcr.io/xila-project/xila-runtime</code> on eligible pushes. <code>latest</code> follows the default branch; releases receive matching <code>v*</code> tags, and published builds receive a commit-SHA tag.</p><p>The image runs as UID/GID <strong>10001</strong>, retains its mutable disk in <code>/var/lib/xila</code>, and carries an immutable reference image at <code>/usr/share/xila/base.img</code>. Its entrypoint is <code>/usr/bin/xila-runtime</code>, and its default command is <strong><code>shell --network=none</code></strong>. The container currently supports <strong>linux/amd64</strong>, not embedded hardware.</p><h2 id="command-syntax" tabindex="-1">Command syntax <a class="header-anchor" href="#command-syntax" aria-label="Permalink to &quot;Command syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xila-runtime shell [OPTIONS]</span></span>
<span class="line"><span>xila-runtime run [OPTIONS] -- &lt;Xila executable&gt; [arguments...]</span></span></code></pre></div><p>Options available in either mode:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[--disk PATH] [--seed PATH] [--network=none]</span></span>
<span class="line"><span>[--mount host=PATH,xila=PATH,ro|rw[,uid=N,gid=N,file_mode=OCTAL,directory_mode=OCTAL]]</span></span>
<span class="line"><span>[--env KEY=VALUE]...</span></span></code></pre></div><ul><li><code>shell</code> starts Xila&#39;s built-in <code>/applications/executables/command_line_shell</code> and needs stdin to log in. A fresh seeded installation accepts <strong>administrator</strong> with an empty password. It forbids overriding <code>User</code> with <code>--env</code>.</li><li><code>run</code> starts an <strong>absolute</strong> executable path in Xila&#39;s VFS after <code>--</code>. For a WASI guest, use <code>/applications/executables/wasm</code> followed by the guest module&#39;s <strong>Xila VFS path</strong> and any arguments.</li><li><code>--disk PATH</code> selects the mutable LittleFS disk (default: <code>/var/lib/xila/drive.img</code>).</li><li><code>--seed PATH</code> selects the image used <strong>only when no disk exists</strong> (default: <code>/usr/share/xila/base.img</code>).</li><li><code>--network=none</code> is the <strong>only</strong> accepted Xila network mode. Docker&#39;s separate <code>--network none</code> disables container networking.</li><li><code>--mount host=...,xila=...,ro|rw</code> grants an explicitly selected <strong>runtime-host directory</strong> to Xila&#39;s VFS. Optional <code>uid</code>, <code>gid</code>, <code>file_mode</code>, and <code>directory_mode</code> control ownership and permissions.</li><li><code>--env KEY=VALUE</code> adds an explicit guest environment setting; repeat it for multiple settings.</li><li><code>--help</code> and <code>--version</code> display CLI information.</li></ul><h2 id="isolation-and-durability" tabindex="-1">Isolation and durability <a class="header-anchor" href="#isolation-and-durability" aria-label="Permalink to &quot;Isolation and durability&quot;">​</a></h2><p>Host directories must first be mounted into Docker and then separately exposed through Xila&#39;s <code>--mount</code>; a Docker bind mount alone grants no Xila VFS access. Ambient host environment variables are not passed to guests. Use read-only mounts unless writes are necessary.</p><p>A writable volume at <code>/var/lib/xila</code> retains the LittleFS disk across container runs. An existing disk is <strong>never overwritten</strong> by a newer seed. SIGINT/SIGTERM attempts to flush/unmount before exiting; abrupt termination may lose recent writes. The image is non-root and supports a read-only container root filesystem with writable state and a temporary <code>/tmp</code>.</p><p>This runner does not provide a graphical desktop, host sockets, an enabled Xila network stack, hardware acceleration, embedded-board support, or sandbox guarantees beyond Docker&#39;s own isolation. Guest compatibility remains limited to the WASI API subset Xila implements.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2>`,15)),a("ul",null,[e[3]||(e[3]=a("li",null,[a("a",{href:"/how-to/run-container-guest.html"},"Run Xila with Docker"),t(" for shell and guest commands.")],-1)),e[4]||(e[4]=a("li",null,[a("a",{href:"/reference/wasm-runtime.html"},"WASM runtime"),t(".")],-1)),a("li",null,[n(s,{repo:"platforms",path:"examples/native/src/bin/xila-runtime.rs"}),e[0]||(e[0]=t(".",-1))]),a("li",null,[n(s,{repo:"platforms",path:"Dockerfile.runtime"}),e[1]||(e[1]=t(".",-1))]),a("li",null,[n(s,{repo:"platforms",path:".github/workflows/runtime.yml"}),e[2]||(e[2]=t(".",-1))])])])}const k=o(c,[["render",m]]);export{x as __pageData,k as default};
